static const int extraLayerIDs[]={LAYER_A,LAYER_A_DEPTH,LAYER_B,LAYER_B_DEPTH,LAYER_C,LAYER_C_DEPTH,GLITTER_MATTE};
static bool layerID(int id){if(id==DEPTH_LAYER)return true;for(int n:extraLayerIDs)if(n==id)return true;return false;}
static bool groupID(int id){for(int n:{LENS_GROUP,LENS_END,FOCUS_GROUP,FOCUS_END,DEPTH_GROUP,DEPTH_END,CREATIVE_GROUP,CREATIVE_END,SHIMMER_GROUP,SHIMMER_END,QUALITY_GROUP,QUALITY_END,CUT_PIXELS_GROUP,CUT_PIXELS_END,LAYER_GROUP,LAYER_END})if(n==id)return true;return false;}
